window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6616e1a332fdea9a"]={"versions": [{"id": "FIG-6616e1a332fdea9a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Port-Spezifikation (AUTOSAR Adaptive Platform UML-Profil).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im Functional Cluster <strong>Communication Management</strong> (<code>ara::com</code>) der AUTOSAR Adaptive Platform.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation standardisierter Schnittstellen zur Übertragung unmodellierter, roher Byteströme (<strong>Raw Data Streams</strong>) zwischen einer <code>Adaptive Application</code> und der Plattform. Die Schnittstelle dient als performante Abstraktion für volumetrische Daten (z. B. Video-, Audio-, Radar- oder Sensor-Rohdaten), bei denen die Serialisierung und der Overhead serviceorientierter Protokolle (SOME/IP) vermieden werden müssen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten:</strong></li>\n<li><code>Adaptive Application</code>: Anwendungsprozess im User-Space, agiert je nach Use-Case als Stream-Consumer, Stream-Producer oder Gateway.</li>\n<li><code>«aapFunctionalCluster» Communication Management</code>: Plattform-Dienst/Cluster, der die systemnahe Streaming-Infrastruktur kapselt (z. B. über POSIX-Sockets, Shared-Memory oder Unix Domain Sockets).</li>\n<li><strong>Schnittstellen & Stereotypen:</strong></li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamClient</code>: Client-Endpunkt für ausgehende Verbindungen.</li>\n<li><code>+ Connect()</code>: Baut aktive Verbindung zum Ziel-Endpunkt auf.</li>\n<li><code>+ ReadData()</code>: Liest Byteströme aus dem Puffer/Kanal.</li>\n<li><code>+ WriteData()</code>: Schreibt Rohdaten in den Kanal.</li>\n<li><code>+ Shutdown()</code>: Führt geordneten Verbindungsabbau durch.</li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamServer</code>: Server-Endpunkt zur Entgegennahme eingehender Verbindungen.</li>\n<li><code>+ WaitForConnection()</code>: Wartet auf eingehende Verbindungsanfragen (Passiv-Listen/Accept).</li>\n<li><code>+ ReadData()</code>: Liest eingehende Nutzlast.</li>\n<li><code>+ WriteData()</code>: Sendet Daten an den verbundenen Client.</li>\n<li><code>+ Shutdown()</code>: Beendet die Verbindung bzw. schließt den Server-Socket.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Interface Realization (<code>«aapProvidedPort»</code>):</strong> Das <code>Communication Management</code> implementiert und exponiert beide Schnittstellen über bereitgestellte Ports.</li>\n<li><strong>Dependency (<code>«use»</code>):</strong> Die <code>Adaptive Application</code> bindet die Schnittstellen über Required Ports (<code>«aapRequiredPort»</code>-Äquivalent auf API-Ebene) an, um Stream-Sitzungen zu steuern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Verbindungsinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Server-Pfad:</strong> Initialisierung der Server-Instanz $\\rightarrow$ Aufruf von <code>WaitForConnection()</code>. Blockiert synchron oder operiert asynchron (Rückgabe via <code>ara::core::Future</code>), bis ein Client anklopft.</li>\n<li><strong>Client-Pfad:</strong> Initialisierung der Client-Instanz $\\rightarrow$ Aufruf von <code>Connect()</code>. Initiiert den Handshake zum konfigurierten Endpunkt (IP/Port oder IPC-Socket).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Datentransfer-Phase (Vollduplex / Halbduplex):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Senden: Aufruf von <code>WriteData()</code> mit Datenzeiger und Längenangabe. Pufferung erfolgt im underlying Transportpuffer des OS-Kernels/Treibers.</li>\n<li>Empfang: Aufruf von <code>ReadData()</code>. Übergabe von Ziel-Puffern; Rückgabe der tatsächlich gelesenen Byteanzahl oder eines <code>ara::core::Result&lt;void&gt;</code> bzw. Fehlercodes (z. B. Puffer-Überlauf, EOF).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Initiator ruft <code>Shutdown()</code> auf $\\rightarrow$ Flush verbleibender Daten $\\rightarrow$ TCP-FIN/RST oder Schließen des IPC-File-Descriptors $\\rightarrow$ Gegenstelle detektiert EOF in <code>ReadData()</code> und beendet die Sitzung ebenfalls mit <code>Shutdown()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag & Fehlermodell:</strong> Die Methoden folgen dem C++14/C++17-Paradigma der Adaptive Platform. Rückgabewerte und asynchrone Ergebnisse sind typischerweise über <code>ara::core::Result&lt;T&gt;</code> bzw. <code>ara::core::Future&lt;T&gt;</code> gekapselt (keine C++ Exceptions).</li>\n<li><strong>Abgrenzung zu Service Interfaces:</strong> Im Gegensatz zu modellierten Service Interfaces (Events, Methods, Fields) existiert kein typisiertes IDL-Schema (keine Serialisierung via SOME/IP Transformer). Entwickler sind selbst für Framing, Synchronisationsmuster (z. B. Paket-Header, Magic Bytes) und Endianness zuständig.</li>\n<li><strong>Laufzeit- & Speichereffizienz:</strong></li>\n<li>Zur Vermeidung von Cache-Trashing und CPU-Kopieraufwand unterstützen typische Stack-Implementierungen Zero-Copy-Puffer (z. B. Memory-Mapped IO, POSIX Shared Memory).</li>\n<li>Bei Echtzeit-Streaming müssen Entwickler <code>ReadData()</code>- und <code>WriteData()</code>-Threads deterministisch priorisieren, um Pufferüberläufe im Kernel-Space (Socket-Drop) zu verhindern.</li>\n<li><strong>ARXML-Manifestierung:</strong> Die Schnittstellen müssen im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> korrekt auf Netzwerk-Endpunkte (IP-Adressen, Ports, Transport-Layer-Protokoll TCP/UDP) gemappt und den Prozess-Berechtigungen (POSIX Capabilities / Access Control) zugewiesen werden.</li>\n</ul>"}, {"id": "FIG-7fd8c2b81a85a0e6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Port-Spezifikation (AUTOSAR Adaptive Platform UML-Profil).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im Functional Cluster <strong>Communication Management</strong> (<code>ara::com</code>) der AUTOSAR Adaptive Platform.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation standardisierter Schnittstellen zur Übertragung unmodellierter, roher Byteströme (<strong>Raw Data Streams</strong>) zwischen einer <code>Adaptive Application</code> und der Plattform. Die Schnittstelle dient als performante Abstraktion für volumetrische Daten (z. B. Video-, Audio-, Radar- oder Sensor-Rohdaten), bei denen die Serialisierung und der Overhead serviceorientierter Protokolle (SOME/IP) vermieden werden müssen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten:</strong></li>\n<li><code>Adaptive Application</code>: Anwendungsprozess im User-Space, agiert je nach Use-Case als Stream-Consumer, Stream-Producer oder Gateway.</li>\n<li><code>«aapFunctionalCluster» Communication Management</code>: Plattform-Dienst/Cluster, der die systemnahe Streaming-Infrastruktur kapselt (z. B. über POSIX-Sockets, Shared-Memory oder Unix Domain Sockets).</li>\n<li><strong>Schnittstellen & Stereotypen:</strong></li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamClient</code>: Client-Endpunkt für ausgehende Verbindungen.</li>\n<li><code>+ Connect()</code>: Baut aktive Verbindung zum Ziel-Endpunkt auf.</li>\n<li><code>+ ReadData()</code>: Liest Byteströme aus dem Puffer/Kanal.</li>\n<li><code>+ WriteData()</code>: Schreibt Rohdaten in den Kanal.</li>\n<li><code>+ Shutdown()</code>: Führt geordneten Verbindungsabbau durch.</li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamServer</code>: Server-Endpunkt zur Entgegennahme eingehender Verbindungen.</li>\n<li><code>+ WaitForConnection()</code>: Wartet auf eingehende Verbindungsanfragen (Passiv-Listen/Accept).</li>\n<li><code>+ ReadData()</code>: Liest eingehende Nutzlast.</li>\n<li><code>+ WriteData()</code>: Sendet Daten an den verbundenen Client.</li>\n<li><code>+ Shutdown()</code>: Beendet die Verbindung bzw. schließt den Server-Socket.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Interface Realization (<code>«aapProvidedPort»</code>):</strong> Das <code>Communication Management</code> implementiert und exponiert beide Schnittstellen über bereitgestellte Ports.</li>\n<li><strong>Dependency (<code>«use»</code>):</strong> Die <code>Adaptive Application</code> bindet die Schnittstellen über Required Ports (<code>«aapRequiredPort»</code>-Äquivalent auf API-Ebene) an, um Stream-Sitzungen zu steuern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Verbindungsinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Server-Pfad:</strong> Initialisierung der Server-Instanz $\\rightarrow$ Aufruf von <code>WaitForConnection()</code>. Blockiert synchron oder operiert asynchron (Rückgabe via <code>ara::core::Future</code>), bis ein Client anklopft.</li>\n<li><strong>Client-Pfad:</strong> Initialisierung der Client-Instanz $\\rightarrow$ Aufruf von <code>Connect()</code>. Initiiert den Handshake zum konfigurierten Endpunkt (IP/Port oder IPC-Socket).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Datentransfer-Phase (Vollduplex / Halbduplex):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Senden: Aufruf von <code>WriteData()</code> mit Datenzeiger und Längenangabe. Pufferung erfolgt im underlying Transportpuffer des OS-Kernels/Treibers.</li>\n<li>Empfang: Aufruf von <code>ReadData()</code>. Übergabe von Ziel-Puffern; Rückgabe der tatsächlich gelesenen Byteanzahl oder eines <code>ara::core::Result&lt;void&gt;</code> bzw. Fehlercodes (z. B. Puffer-Überlauf, EOF).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Initiator ruft <code>Shutdown()</code> auf $\\rightarrow$ Flush verbleibender Daten $\\rightarrow$ TCP-FIN/RST oder Schließen des IPC-File-Descriptors $\\rightarrow$ Gegenstelle detektiert EOF in <code>ReadData()</code> und beendet die Sitzung ebenfalls mit <code>Shutdown()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag & Fehlermodell:</strong> Die Methoden folgen dem C++14/C++17-Paradigma der Adaptive Platform. Rückgabewerte und asynchrone Ergebnisse sind typischerweise über <code>ara::core::Result&lt;T&gt;</code> bzw. <code>ara::core::Future&lt;T&gt;</code> gekapselt (keine C++ Exceptions).</li>\n<li><strong>Abgrenzung zu Service Interfaces:</strong> Im Gegensatz zu modellierten Service Interfaces (Events, Methods, Fields) existiert kein typisiertes IDL-Schema (keine Serialisierung via SOME/IP Transformer). Entwickler sind selbst für Framing, Synchronisationsmuster (z. B. Paket-Header, Magic Bytes) und Endianness zuständig.</li>\n<li><strong>Laufzeit- & Speichereffizienz:</strong></li>\n<li>Zur Vermeidung von Cache-Trashing und CPU-Kopieraufwand unterstützen typische Stack-Implementierungen Zero-Copy-Puffer (z. B. Memory-Mapped IO, POSIX Shared Memory).</li>\n<li>Bei Echtzeit-Streaming müssen Entwickler <code>ReadData()</code>- und <code>WriteData()</code>-Threads deterministisch priorisieren, um Pufferüberläufe im Kernel-Space (Socket-Drop) zu verhindern.</li>\n<li><strong>ARXML-Manifestierung:</strong> Die Schnittstellen müssen im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> korrekt auf Netzwerk-Endpunkte (IP-Adressen, Ports, Transport-Layer-Protokoll TCP/UDP) gemappt und den Prozess-Berechtigungen (POSIX Capabilities / Access Control) zugewiesen werden.</li>\n</ul>"}, {"id": "FIG-95a69a366175e036", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Port-Spezifikation (AUTOSAR Adaptive Platform UML-Profil).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im Functional Cluster <strong>Raw Data Stream</strong> der AUTOSAR Adaptive Platform.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation standardisierter Schnittstellen zur Übertragung unmodellierter, roher Byteströme (<strong>Raw Data Streams</strong>) zwischen einer <code>Adaptive Application</code> und der Plattform. Die Schnittstelle dient als performante Abstraktion für volumetrische Daten (z. B. Video-, Audio-, Radar- oder Sensor-Rohdaten), bei denen die Serialisierung und der Overhead serviceorientierter Protokolle (SOME/IP) vermieden werden müssen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten:</strong></li>\n<li><code>Adaptive Application</code>: Anwendungsprozess im User-Space, agiert je nach Use-Case als Stream-Consumer, Stream-Producer oder Gateway.</li>\n<li><code>«aapFunctionalCluster» Raw Data Stream</code>: Plattform-Dienst/Cluster, der die systemnahe Streaming-Infrastruktur kapselt (z. B. über POSIX-Sockets, Shared-Memory oder Unix Domain Sockets).</li>\n<li><strong>Schnittstellen & Stereotypen:</strong></li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamClient</code>: Client-Endpunkt für ausgehende Verbindungen.</li>\n<li><code>+ Connect()</code>: Baut aktive Verbindung zum Ziel-Endpunkt auf.</li>\n<li><code>+ ReadData()</code>: Liest Byteströme aus dem Puffer/Kanal.</li>\n<li><code>+ WriteData()</code>: Schreibt Rohdaten in den Kanal.</li>\n<li><code>+ Shutdown()</code>: Führt geordneten Verbindungsabbau durch.</li>\n<li><code>«aapAPI,aapPortInterface» RawDataStreamServer</code>: Server-Endpunkt zur Entgegennahme eingehender Verbindungen.</li>\n<li><code>+ WaitForConnection()</code>: Wartet auf eingehende Verbindungsanfragen (Passiv-Listen/Accept).</li>\n<li><code>+ ReadData()</code>: Liest eingehende Nutzlast.</li>\n<li><code>+ WriteData()</code>: Sendet Daten an den verbundenen Client.</li>\n<li><code>+ Shutdown()</code>: Beendet die Verbindung bzw. schließt den Server-Socket.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Interface Realization:</strong> Der Functional Cluster <code>Raw Data Stream</code> implementiert und exponiert beide Schnittstellen über Realisierungsbeziehungen.</li>\n<li><strong>Dependency (<code>«use»</code>, <code>«aapRequiredPort»</code>):</strong> Die <code>Adaptive Application</code> bindet die Schnittstellen über explizit mit <code>«use»</code> und <code>«aapRequiredPort»</code> modellierte Abhängigkeiten an, um Stream-Sitzungen zu steuern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Verbindungsinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Server-Pfad:</strong> Initialisierung der Server-Instanz $\\rightarrow$ Aufruf von <code>WaitForConnection()</code>. Blockiert synchron oder operiert asynchron (Rückgabe via <code>ara::core::Future</code>), bis ein Client anklopft.</li>\n<li><strong>Client-Pfad:</strong> Initialisierung der Client-Instanz $\\rightarrow$ Aufruf von <code>Connect()</code>. Initiiert den Handshake zum konfigurierten Endpunkt (IP/Port oder IPC-Socket).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Datentransfer-Phase (Vollduplex / Halbduplex):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Senden: Aufruf von <code>WriteData()</code> mit Datenzeiger und Längenangabe. Pufferung erfolgt im underlying Transportpuffer des OS-Kernels/Treibers.</li>\n<li>Empfang: Aufruf von <code>ReadData()</code>. Übergabe von Ziel-Puffern; Rückgabe der tatsächlich gelesenen Byteanzahl oder eines <code>ara::core::Result&lt;void&gt;</code> bzw. Fehlercodes (z. B. Puffer-Überlauf, EOF).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Initiator ruft <code>Shutdown()</code> auf $\\rightarrow$ Flush verbleibender Daten $\\rightarrow$ TCP-FIN/RST oder Schließen des IPC-File-Descriptors $\\rightarrow$ Gegenstelle detektiert EOF in <code>ReadData()</code> und beendet die Sitzung ebenfalls mit <code>Shutdown()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag & Fehlermodell:</strong> Die Methoden folgen dem C++14/C++17-Paradigma der Adaptive Platform. Rückgabewerte und asynchrone Ergebnisse sind typischerweise über <code>ara::core::Result&lt;T&gt;</code> bzw. <code>ara::core::Future&lt;T&gt;</code> gekapselt (keine C++ Exceptions).</li>\n<li><strong>Abgrenzung zu Service Interfaces:</strong> Im Gegensatz zu modellierten Service Interfaces (Events, Methods, Fields) existiert kein typisiertes IDL-Schema (keine Serialisierung via SOME/IP Transformer). Entwickler sind selbst für Framing, Synchronisationsmuster (z. B. Paket-Header, Magic Bytes) und Endianness zuständig.</li>\n<li><strong>Laufzeit- & Speichereffizienz:</strong></li>\n<li>Zur Vermeidung von Cache-Trashing und CPU-Kopieraufwand unterstützen typische Stack-Implementierungen Zero-Copy-Puffer (z. B. Memory-Mapped IO, POSIX Shared Memory).</li>\n<li>Bei Echtzeit-Streaming müssen Entwickler <code>ReadData()</code>- und <code>WriteData()</code>-Threads deterministisch priorisieren, um Pufferüberläufe im Kernel-Space (Socket-Drop) zu verhindern.</li>\n<li><strong>ARXML-Manifestierung:</strong> Die Schnittstellen müssen im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> korrekt auf Netzwerk-Endpunkte (IP-Adressen, Ports, Transport-Layer-Protokoll TCP/UDP) gemappt und den Prozess-Berechtigungen (POSIX Capabilities / Access Control) zugewiesen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-6616e1a332fdea9a", "to": "FIG-7fd8c2b81a85a0e6", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7fd8c2b81a85a0e6", "to": "FIG-95a69a366175e036", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Functional Cluster:</strong> Der bereitstellende Functional Cluster wurde von <code>Communication Management</code> in <code>Raw Data Stream</code> geändert.</li>\n<li><strong>Port-Stereotypen an <code>Adaptive Application</code>:</strong> Die Abhängigkeitspfeile (<code>«use»</code>) von <code>Adaptive Application</code> zu <code>RawDataStreamClient</code> und <code>RawDataStreamServer</code> wurden um das Stereotyp <code>«aapRequiredPort»</code> ergänzt.</li>\n<li><strong>Port-Stereotypen an Realisierungsbeziehungen:</strong> An den Realisierungspfeilen vom Functional Cluster <code>Raw Data Stream</code> zu <code>RawDataStreamClient</code> und <code>RawDataStreamServer</code> ist die Beschriftung <code>«aapProvidedPort»</code> entfallen.</li>\n</ul>"}]};
